549	/**
550	 * Works out the sheet's figures as the screen shows them, and records in the audit file how a change
551	 * moved them: ROLLUP sheet=<id> by=<user> person=<name> claimed=<0.00> due-total=<0.00 or n/a> for each
552	 * person whose figures changed (a person new to the sheet counts as changed), in the order they were
553	 * added, then TOTALS sheet=<id> by=<user> claimed-total=<0.00> due-total=<0.00> when the sheet's totals
554	 * changed. A change that moves no figure records nothing here.
555	 */
556	@Service
557	public class RollupService {
558	
559	    private static final String NA = "n/a";
560	
561	    private final PersonStore people;
562	    private final ClaimStore claims;
563	    private final RateStore rates;
564	    private final SheetStore sheets;
565	    private final Audit audit;
566	
567	    public RollupService(PersonStore people, ClaimStore claims, RateStore rates, SheetStore sheets, Audit audit) {
568	        this.people = people;
569	        this.claims = claims;
570	        this.rates = rates;
571	        this.sheets = sheets;
572	        this.audit = audit;
573	    }
574	
575	    /** The sheet's figures as the store holds them now. */
576	    public Rollup snapshot(String sheetId) {
577	        LocalDate today = sheets.today(sheetId);
578	        List<Claim> all = claims.list(sheetId);
579	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
580	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
581	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
582	        for (Person person : people.list(sheetId)) {
583	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
584	            BigDecimal due = BigDecimal.ZERO.setScale(2);
585	            boolean fixed = false;
586	            for (Claim claim : all) {
587	                if (claim.getPersonId() != person.getId()
588	                        || (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.SETTLED)) {
589	                    continue;
590	                }
591	                claimed = claimed.add(claim.getAmount());
592	                BigDecimal figure = ClaimFigure.of(claim, rates.find(sheetId, person.getGrade(), claim.getDate()));
593	                if (figure != null) {
594	                    due = due.add(figure);
595	                }
596	                fixed |= claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
597	            }
598	            boolean na = rates.find(sheetId, person.getGrade(), today) == null && !fixed;
599	            claimedTotal = claimedTotal.add(claimed);
600	            if (!na) {
601	                dueTotal = dueTotal.add(due);
602	            }
603	            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due)));
604	        }
605	        return new Rollup(figures, shown(claimedTotal), shown(dueTotal));
606	    }
607	
608	    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
609	    public void record(String sheetId, String user, Rollup before) {
610	        Rollup after = snapshot(sheetId);
611	        String who = " sheet=" + sheetId + " by=" + user;
612	        after.people().forEach((id, now) -> {
613	            if (!now.sameAs(before.people().get(id))) {
614	                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
615	                        + now.dueTotal());
616	            }
617	        });
618	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())) {
619	            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
620	        }
621	    }
622	
623	    private static String shown(BigDecimal value) {
624	        return value.setScale(2).toPlainString();
625	    }
626	}
