640	package net.officefloor.hq.app;
641	
642	import java.io.IOException;
643	import java.io.UncheckedIOException;
644	import java.nio.charset.StandardCharsets;
645	import java.nio.file.Files;
646	import java.nio.file.Path;
647	import java.nio.file.StandardOpenOption;
648	import org.springframework.beans.factory.annotation.Value;
649	import org.springframework.stereotype.Service;
650	
651	/**
652	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
653	 * so tests can assert side-effects by reading that file — the second test-assertion channel
654	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
655	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
656	 *
657	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
658	 * SYNC) so a test reads the record immediately.
659	 */
660	@Service
661	public class Audit {
662	
663	    private final Path file;
664	
665	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
666	        this.file = Path.of(path);
667	    }
668	
669	    /** Append one audit record. Tests assert the exact line(s) in the file. */
670	    public synchronized void record(String entry) {
671	        try {
672	            Path parent = file.toAbsolutePath().getParent();
673	            if (parent != null) {
674	                Files.createDirectories(parent);
675	            }
676	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
677	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
678	        } catch (IOException e) {
679	            throw new UncheckedIOException(e);
680	        }
681	    }
682	
683	    /** Remove the audit file. */
684	    public synchronized void clear() {
685	        try {
686	            Files.deleteIfExists(file);
687	        } catch (IOException e) {
688	            throw new UncheckedIOException(e);
689	        }
690	    }
691	}
