                {close.isError && close.variables === p.name && (
                  <span data-testid="period-error" role="alert">
                    {' '}
                    {close.error instanceof HttpError && close.error.reason ? `${close.error.reason}.` : 'The period was refused.'}
                  </span>
                )}
              </td>
''')
open(p,'w').write(s)
EOF
